import {readFileSync, writeFileSync} from 'node:fs';
import assert from 'node:assert/strict';
const [from, to] = process.argv.slice(2);
const code = readFileSync(from, 'utf8').replaceAll('\r\n', '\n');
const marker = 'function _M0FP210JingLan0v03stn17planning__problem(';
const start = code.indexOf(marker);
const end = code.indexOf('\nfunction ', start + marker.length);
const body = code.slice(start, end);
const loop = /^  let _tmp\$2 = 0;$/m;
assert(start >= 0 && end > start && loop.test(body));
const split = body.search(loop);
const tasks = body.slice(0, split)
  .replace(/_M0MPC13int3Int18to__string_2einner\(i, 10\)/g, '(counts.suffixes++, $&)')
  .replace(/_M0FP210JingLan0v03stn5point\(i, (false|true)\)/g, '(counts.suffixes++, $&)');
const instrumented = tasks.replace(marker + 'tasks, dependencies) {',
  marker + 'tasks, dependencies) {\n  const taskStarted = performance.now();') +
  '  counts.taskPassMs += performance.now() - taskStarted; counts.builds++;\n' + body.slice(split);
assert(instrumented.includes('const taskStarted'));
writeFileSync(to, 'const counts = {builds:0,suffixes:0,taskPassMs:0};\n' +
  "process.once('exit', () => console.error(JSON.stringify(counts)));\n" + code.slice(0, start) + instrumented + code.slice(end));

